async function api(url,opts={}){const r=await fetch(url,{credentials:'same-origin',...opts});let d;try{d=await r.json()}catch{d={}}if(!r.ok)throw new Error(d.error||`Permintaan gagal (${r.status})`);return d}
function toast(s){let t=$('#toast');if(!t){t=document.createElement('div');t.id='toast';t.className='toast';document.body.append(t)}t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),3000)}
function dateFmt(v){if(!v)return '-';const d=new Date(v+'T00:00:00');return isNaN(d)?v:d.toLocaleDateString('id-ID',{day:'numeric',month:'long',year:'numeric'})}
function inputDate(v){if(!v)return '';if(/^\d{4}-\d\d-\d\d$/.test(v))return v;const d=new Date(v);return isNaN(d)?'':d.toISOString().slice(0,10)}
function phone(){return (localStorage.getItem('pdm_leader_whatsapp')||'').replace(/\D/g,'')}
function wa(text){const p=phone();if(p.length<10){toast('Atur nomor WhatsApp pimpinan terlebih dahulu.');$('#whatsappSettings')?.classList.remove('hidden');return}window.open(`https://wa.me/${p}?text=${encodeURIComponent(text)}`,'_blank','noopener')}
const polite=`Yth Bapak Pimpinan,\nDengan hormat, kami menyampaikan informasi surat masuk PT Digital Mandiri.\nMohon kesediaan Bapak untuk meninjau informasi tersebut dan memberikan arahan tindak lanjut apabila diperlukan.\nTerima kasih atas perhatian dan arahannya.\nHormat kami,\nSekretariat\nPT Digital Mandiri`;
function formatMail(m,i){const u=activeUser();const role=u?.role||'admin';const leader=role==='pemimpin';const canEdit=!leader;const disp=dispositionCache[String(m.id)];const dispApproved=disp?.approval_status==='Disetujui';const dispLabel=dispApproved?'Disposisi sudah di-ACC':'Belum di-ACC';return `<tr data-id="${esc(m.id)}"><td>${i+1}</td><td>${esc(dateFmt(m.received_date))}</td><td>${esc(m.number)}</td><td>${esc(dateFmt(m.letter_date))}</td><td>${esc(m.party)}</td><td>${esc(m.subject)}</td><td>${esc(m.summary)}</td><td>${esc(m.code||'-')}</td><td><div class="status-stack"><span class="status ${m.status==='Diproses'?'review':''}">${esc(m.status)}</span>${isIn?`<span class="status ${dispApproved?'approved':'review'}">${dispLabel}</span>`:''}</div></td><td><div class="table-actions"><button class="btn btn-light btn-sm print-mail" data-id="${esc(m.id)}" title="Cetak surat">🖨 Cetak</button>${isOut&&canEdit?`<a class="btn btn-light btn-sm download-mail ${m.pdf?'':'disabled-download'}" data-id="${esc(m.id)}" ${m.pdf?`href="/api/mails/${encodeURIComponent(m.id)}/pdf?download=1"`:''} title="Unduh surat PDF">Unduh Surat</a>`:''}${canEdit?`<button class="btn btn-light btn-sm edit-mail" data-id="${esc(m.id)}">Edit</button>`:''}${role==='admin'?`<button class="btn btn-danger btn-sm delete-row" data-id="${esc(m.id)}">Hapus</button>`:''}${isIn?`<a class="btn btn-outline btn-sm" href="detail-surat.html?id=${encodeURIComponent(m.id)}">${leader?'Tinjau Disposisi':'Disposisi'}</a>`:''}</div></td></tr>`}
let mailCache=[];
let dispositionCache={};
async function loadMails(){if(!isIn&&!isOut)return;const q=$('#tableSearch')?.value||'';const code=new URLSearchParams(location.search).get('kode')||'';const data=await api(`/api/mails?type=${kind}&q=${encodeURIComponent(q)}${code?'&code='+encodeURIComponent(code):''}`);mailCache=data;if(isIn){try{const dispositions=await api('/api/dispositions');dispositionCache={};(Array.isArray(dispositions)?dispositions:[]).forEach(d=>{if(d.mail_id!==undefined&&d.mail_id!==null)dispositionCache[String(d.mail_id)]=d;});}catch(err){dispositionCache={};}}const body=$('.table-wrap tbody');if(body)body.innerHTML=data.map(formatMail).join('')||'<tr><td colspan="10">Belum ada data surat.</td></tr>';}
function populateSubclasses(){}
function openMailModal(m=null){const modal=$('#addMailModal'),form=$('#addMailForm');if(!modal||!form){toast('Form surat tidak ditemukan.');return}form.reset();delete form.dataset.editId;form.dataset.kind=kind;const title=$('h2',form);if(title)title.textContent=(m?'Edit ':'Tambah ')+(isIn?'Surat Masuk':'Surat Keluar');if(m){form.dataset.editId=m.id;const set=(n,v)=>{if(form.elements[n])form.elements[n].value=v||''};set(isIn?'tanggalTerima':'tanggalKirim',m.received_date);set('nomorSurat',m.number);set('tanggalSurat',m.letter_date);set(isIn?'dari':'kepada',m.party);set('perihal',m.subject);if(form.elements.kodeArsip)form.elements.kodeArsip.value=m.code||'';set('isiRingkas',m.summary);if(form.elements.subKodeArsip)form.elements.subKodeArsip.value=m.sub_code||''}populateSubclasses();modal.classList.add('show')}
function printMail(m){if(m?.pdf){if(!m.id){toast('ID surat tidak tersedia untuk membuka PDF asli.');return}const pdfUrl=`/api/mails/${encodeURIComponent(m.id)}/pdf`;const opened=window.open(pdfUrl,'_blank');if(!opened){toast('Izinkan pop-up browser untuk mencetak PDF asli.');return}try{opened.addEventListener('load',()=>{try{opened.focus();opened.print()}catch(_){}})}catch(_){}return}const win=window.open('','_blank','width=1000,height=750');if(!win){toast('Izinkan pop-up untuk mencetak.');return}const title=`LEMBAR DATA SURAT ${isIn?'MASUK':'KELUAR'}`;win.document.write(`<!doctype html><html lang="id"><meta charset="utf-8"><title>${title}</title><style>@page{size:A4 portrait;margin:15mm}body{font:13px Arial;padding:18px;color:#173b63}h2,p{text-align:center}table{border-collapse:collapse;width:100%;margin-top:24px}td{border:1px solid #789;padding:9px;vertical-align:top}td:first-child{font-weight:bold;width:28%;background:#eef6ff} .sign{margin-top:45px;display:flex;justify-content:space-between}@media print{body{padding:0}}</style><h2>PT DIGITAL MANDIRI</h2><p>SISTEM INFORMASI KEARSIPAN DIGITAL<br>${title}</p><table>${[['Nomor Surat',m.number],['Tanggal Terima/Kirim',dateFmt(m.received_date)],['Tanggal Surat',dateFmt(m.letter_date)],['Dari/Kepada',m.party],['Perihal',m.subject],['Isi Ringkas',m.summary],['Kode Arsip',m.code],['Status',m.status]].map(x=>`<tr><td>${esc(x[0])}</td><td>${esc(x[1])}</td></tr>`).join('')}</table><div class="sign"><span>Petugas Pencatat: ____________________</span><span>Makassar, ${new Date().toLocaleDateString('id-ID')}<br>Mengetahui: ____________________</span></div><script>window.onload=()=>window.print()<\/script></html>`);win.document.close()}
async function saveMailForm(form){const fd=new FormData(form);const wasEdit=!!form.dataset.editId;const payload={kind, tanggalTerima:fd.get('tanggalTerima'),tanggalKirim:fd.get('tanggalKirim'),nomorSurat:fd.get('nomorSurat'),tanggalSurat:fd.get('tanggalSurat'),dari:fd.get('dari'),kepada:fd.get('kepada'),perihal:fd.get('perihal'),kodeArsip:fd.get('kodeArsip'),subKodeArsip:fd.get('subKodeArsip'),isiRingkas:fd.get('isiRingkas')};const file=form.elements.lampiranPDF?.files?.[0];let opts;if(file){fd.set('kind',kind);opts={method:wasEdit?'PUT':'POST',body:fd}}else opts={method:wasEdit?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)};const url=wasEdit?`/api/mails/${form.dataset.editId}`:'/api/mails';await api(url,opts);$('#addMailModal')?.classList.remove('show');form.reset();delete form.dataset.editId;await loadMails();toast('Data surat tersimpan di database.');if(isIn&&!wasEdit)wa(polite)}
