 if(b.matches('.delete-row')){e.preventDefault();if(confirm('Yakin menghapus surat ini dari database?')){await api('/api/mails/'+b.dataset.id,{method:'DELETE'});await loadMails();toast('Surat dihapus dari database.')}return}
 if(b.matches('.attach-pdf')){e.preventDefault();b.nextElementSibling?.click();return}
