 if(b.matches('.demo-action')){e.preventDefault();const label=b.textContent.toLowerCase();if(label.includes('lihat arsip'))return showClassMails((b.textContent.match(/\d{3}/)||[])[0]);if(label.includes('ajukan peminjaman')){await openLoanForm();return}if(label.includes('tambah pengguna')){const full=prompt('Nama lengkap:');if(full===null)return;const username=prompt('Username:');if(username===null)return;const role=prompt('Peran (Admin/Sekretaris/Pemimpin):','Sekretaris');if(role===null)return;const email=prompt('Email:','');if(email===null)return;await api('/api/users',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({full_name:full,username,role,email})});await renderUsers();toast('Pengguna disimpan ke database.');return}if(label.includes('edit profil')){const name=prompt('Nama pengguna:',localStorage.getItem('pdm_profile_name')||'Nazwa Azzahra');if(name===null)return;localStorage.setItem('pdm_profile_name',name);toast('Profil lokal diperbarui.');return}if(label==='filter'){setMailFilter();return}toast(b.dataset.message||'Aksi dilakukan.');return}
 if(b.matches('.leader-approve')){if(!confirm('Setujui disposisi ini dan tampilkan tanda tangan pimpinan?'))return;const result=await api('/api/dispositions/'+b.dataset.id+'/approve',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({approved_by:'Mohd Satryawan Aras'})});await renderLeaderApprovals();toast('Disposisi disetujui. Tanda tangan pimpinan sekarang aktif.');return}
