 document.addEventListener('click',async e=>{
   const choice=e.target.closest('.priority-choice');
   if(!choice || page!=='detail-surat.html') return;
   const id=window.currentDispositionId;
   if(!id) return; // Prioritas awal akan ikut tersimpan saat form disposisi disimpan.
   const selected=choice.dataset.priority;
   const user=activeUser();
   try{
     await api('/api/dispositions/'+encodeURIComponent(id)+'/priority',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({priority:selected,actor:user?.name||user?.username||'Pengguna'})});
     toast('Prioritas '+selected+' tersimpan dan terhubung untuk Admin, Sekretaris, dan Pemimpin.');
   }catch(err){toast('Prioritas gagal disimpan: '+err.message)}
 });
 document.addEventListener('change',async e=>{if(e.target.matches('.mail-attachment')){const f=e.target.files?.[0],tr=e.target.closest('tr');if(!f||!tr)return;if(f.type!=='application/pdf')return toast('Pilih file PDF.');const m=mailCache.find(x=>x.id===tr.dataset.id);if(!m)return;const fd=new FormData();fd.append('kind',m.kind);fd.append('tanggalTerima',m.received_date);fd.append('tanggalSurat',m.letter_date);fd.append('nomorSurat',m.number);fd.append('dari',m.party);fd.append('perihal',m.subject);fd.append('isiRingkas',m.summary);fd.append('kodeArsip',m.code);fd.append('status',m.status);fd.append('lampiranPDF',f);await api('/api/mails/'+m.id,{method:'PUT',body:fd});await loadMails();toast('PDF tersimpan permanen di server.')}if(e.target.matches('.loan-status')){await api('/api/loans/'+e.target.dataset.id,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:e.target.value})});await renderLoans();toast('Status peminjaman diperbarui di database dan riwayat.')} });
